def maxPyramidSequenceSize(N: int, A: List[int]) -> int:
    if N == 0:
        return 0

    left = [0] * N
    right = [0] * N

    left[0] = 1
    for i in range(1, N):
        if A[i] > A[i - 1]:
            left[i] = left[i - 1] + 1
        else:
            left[i] = 1

    right[N - 1] = 1
    for i in range(N - 2, -1, -1):
        if A[i] > A[i + 1]:
            right[i] = right[i + 1] + 1
        else:
            right[i] = 1

    max_size = 0
    for i in range(N):
        max_size = max(max_size, min(left[i], right[i]))

    return max_size
